// Adds texts to src/SScreentify.App/Ui/Strings.resx (if missing) and regenerates Ui/Strings.cs from it.
// WPF's markup build skips resx code generation, so Strings.cs is generated by this script instead.
//
// Usage (from the repo root):
//   node scripts/sync-strings.js                      regenerate Strings.cs only
//   node scripts/sync-strings.js "Key=Texto" ...      add keys, then regenerate
//
// Afterwards update the expected count in tests/SScreentify.App.Tests/ShellTests.cs (Strings_EveryPropertyResolves).
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const resx = path.join(root, 'src/SScreentify.App/Ui/Strings.resx');
const cs = path.join(root, 'src/SScreentify.App/Ui/Strings.cs');

let xml = fs.readFileSync(resx, 'utf8');
const escape = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
for (const pair of process.argv.slice(2)) {
  const i = pair.indexOf('=');
  if (i <= 0) throw new Error(`Expected Key=Text, got: ${pair}`);
  const key = pair.slice(0, i), value = pair.slice(i + 1);
  if (!xml.includes(`<data name="${key}"`))
    xml = xml.replace('</root>', `  <data name="${key}" xml:space="preserve"><value>${escape(value)}</value></data>\n</root>`);
}
fs.writeFileSync(resx, xml);

const keys = [...xml.matchAll(/<data name="([^"]+)"/g)].map(m => m[1]);
let code = 'using System.Globalization;\nusing System.Resources;\n\nnamespace SScreentify.App.Ui;\n\n' +
  '/// <summary>Typed access to Strings.resx (written by hand: WPF markup compilation skips resx code generation).</summary>\n' +
  'public static class Strings\n{\n' +
  '    private static readonly ResourceManager Resources = new("SScreentify.App.Ui.Strings", typeof(Strings).Assembly);\n\n' +
  '    public static CultureInfo? Culture { get; set; }\n\n';
for (const key of keys) code += `    public static string ${key} => Get(nameof(${key}));\n`;
code += '\n    private static string Get(string key) =>\n        Resources.GetString(key, Culture) ?? throw new MissingManifestResourceException(key);\n}\n';
fs.writeFileSync(cs, code);
console.log(`${keys.length} keys`);
